@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
  + IsFree : boolean
}

class Category {
  + Name : string
  + Price : double
}

class StayType {
  + Description : string
}

class RestHome {}
class RestNursingHome {}
class ServiceFlat {}

class Inhabitant {
  + Name : string
  + ID : string
}

class Registration {
  + RegistrationDate : date
  + Status : string
}

class Assessment {
  + NeedsHelpLevel : int
  + ResultingStayType : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + InvoiceNumber : int
  + TotalAmount : double
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + CreditAmount : double
}

class PaymentEvent {
  + AmountPaid : double
  + PaymentDate : datetime
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
StayType "1" -- "1" Category

class RestHome --|> StayType
class RestNursingHome --|> StayType
class ServiceFlat --|> StayType

Inhabitant "1" -- "0..*" Registration
Registration "1" -- "0..1" Assessment
Assessment "1" -- "1" StayType

Inhabitant "1" -- "0..*" Stay
Stay "1" -- "1" StayType
Stay "1" -- "1" Bed

Inhabitant "1" -- "0..*" Proposal
Proposal "1" -- "1" StayType
Proposal "1" -- "0..1" Inhabitant

Inhabitant "1" -- "0..*" Invoice
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

class Stay {
  + StartDate : date
  + EndDate : date
  + IsSuspended : boolean
  + DiscountRate : double
}

@enduml

